changeSet.sql:
INSERT INTO app_setting (id, setting_key, setting_value, value_type, description) SELECT gen_random_uuid(), 'ai.openai.model', setting_value, 'STRING', 'OpenAI model used by the assistant chat' FROM app_setting WHERE setting_key = 'ai.model';
INSERT INTO app_setting (id, setting_key, setting_value, value_type, description) SELECT gen_random_uuid(), 'ai.openai.title_model', setting_value, 'STRING', 'OpenAI model used to name chat conversations' FROM app_setting WHERE setting_key = 'ai.title_model';
INSERT INTO app_setting (id, setting_key, setting_value, value_type, description) VALUES (gen_random_uuid(), 'ai.gemini.model', 'gemini-2.5-flash', 'STRING', 'Google Gemini model used by the assistant chat');
INSERT INTO app_setting (id, setting_key, setting_value, value_type, description) VALUES (gen_random_uuid(), 'ai.gemini.title_model', 'gemini-2.5-flash-lite', 'STRING', 'Google Gemini model used to name chat conversations');
DELETE FROM app_setting WHERE setting_key IN ('ai.model', 'ai.title_model');
UPDATE app_setting SET setting_value = 'gemini', description = 'Active AI vendor adapter id: gemini or openai (see the AI settings page)' WHERE setting_key = 'ai.provider' AND setting_value = 'openai';
